function tenthLine(content) {
  // Read character by character, counting line breaks as sed and awk do.
  let lineNumber = 1;
  let current = '';
  for (const ch of content) {
    if (ch === '\n') {
      if (lineNumber === 10) return current;
      lineNumber += 1;
      current = '';
    } else {
      current += ch;
    }
  }
  // An unterminated last line still counts, but only if it has characters.
  return lineNumber === 10 && current !== '' ? current : '';
}

