function generate(rand, size) {
  const pieces = ['Line', 'alpha', 'beta gamma', 'x', '42', '  padded  ', 'a-b-c', 'tab\there', 'end.'];
  let count;
  if (size === 'small') count = Math.floor(rand() * 15);
  else count = rand() < 0.2 ? Math.floor(rand() * 10) : 10 + Math.floor(rand() * 400);
  const lines = [];
  for (let i = 0; i < count; i++) {
    const roll = rand();
    if (roll < 0.1) lines.push('');
    else if (roll < 0.4) lines.push(`Line ${i + 1}`);
    else lines.push(pieces[Math.floor(rand() * pieces.length)] + (rand() < 0.5 ? ` ${i + 1}` : ''));
  }
  let content = lines.join('\n');
  if (count > 0 && rand() < 0.4) content += '\n';
  return [content];
}
